// ============================================================
// DECISION & PRESCRIPTIVE
// Deterministic Supplier Evaluation Engine
// SNS Workbench Code Node
// Execution Mode: Run Once for All Items
// ============================================================


// ============================================================
// 1. GET ALL INPUT ITEMS
// ============================================================

// SNS Workbench does not provide a global "items" variable.
// Use $input.all() for Run Once for All Items.

const inputItems = $input.all();


// ============================================================
// 2. DATA COLLECTION
// ============================================================

const commercialRecords = [];
const riskRecords = [];
const planningRecords = [];


// ============================================================
// 3. FLATTEN MERGE DATA
// ============================================================
//
// Your Merge Data structure is:
//
// {
//   json: {
//     status: "success",
//     data: {
//       items: [
//         {
//           json: {
//             ...
//           }
//         }
//       ]
//     }
//   }
// }
//
// Therefore we extract data.items[].json
// ============================================================

for (const inputItem of inputItems) {

    const root = inputItem.json || {};

    const dataItems =
        root.data &&
        Array.isArray(root.data.items)
            ? root.data.items
            : [];

    for (const record of dataItems) {

        const row = record.json || record;

        if (!row) {
            continue;
        }


        // ----------------------------------------------------
        // PLANNING / REQUIREMENT RECORD
        // ----------------------------------------------------

        if (
            row.component_code !== undefined &&
            row.total_component_requirement !== undefined
        ) {

            planningRecords.push(row);

            continue;
        }


        // ----------------------------------------------------
        // SUPPLIER COMMERCIAL RECORD
        // ----------------------------------------------------

        if (
            row.supplier_code !== undefined &&
            row.lead_time_days !== undefined &&
            row.reference_unit_price !== undefined
        ) {

            commercialRecords.push(row);

            continue;
        }


        // ----------------------------------------------------
        // SUPPLIER RISK RECORD
        // ----------------------------------------------------

        if (
            row.supplier_code !== undefined &&
            row.operational_status !== undefined
        ) {

            riskRecords.push(row);

            continue;
        }
    }
}


// ============================================================
// 4. HANDLE MISSING PLANNING DATA
// ============================================================

if (planningRecords.length === 0) {

    return [
        {
            json: {
                status: "INSUFFICIENT_DATA",
                decision_type:
                    "SUPPLIER_MITIGATION_EVALUATION",
                reason:
                    "Planning/Requirement data was not found.",
                commercial_supplier_count:
                    commercialRecords.length,
                risk_supplier_count:
                    riskRecords.length,
                planning_record_count:
                    planningRecords.length,
                supplier_options: [],
                human_approval_required: true,
                autonomous_execution_allowed: false
            }
        }
    ];
}


// ============================================================
// 5. HANDLE MISSING SUPPLIER DATA
// ============================================================

if (commercialRecords.length === 0) {

    return [
        {
            json: {
                status: "INSUFFICIENT_DATA",
                decision_type:
                    "SUPPLIER_MITIGATION_EVALUATION",
                reason:
                    "Supplier commercial data was not found.",
                commercial_supplier_count:
                    commercialRecords.length,
                risk_supplier_count:
                    riskRecords.length,
                planning_record_count:
                    planningRecords.length,
                supplier_options: [],
                human_approval_required: true,
                autonomous_execution_allowed: false
            }
        }
    ];
}


// ============================================================
// 6. EXTRACT PLANNING INFORMATION
// ============================================================

const planning = planningRecords[0];


// Required component quantity
const requiredQuantity =
    Number(
        planning.total_component_requirement || 0
    );


// Current available inventory
const availableInventory =
    Number(
        planning.available_inventory || 0
    );


// Actual shortage
const shortageQuantity =
    Math.max(
        0,
        requiredQuantity - availableInventory
    );


// ============================================================
// 7. CALCULATE DAYS UNTIL REQUIRED DATE
// ============================================================

const requiredDeliveryDate =
    new Date(
        planning.required_delivery_date
    );

const today =
    new Date();


// Normalize dates to midnight
today.setHours(0, 0, 0, 0);

requiredDeliveryDate.setHours(0, 0, 0, 0);


let daysUntilRequiredDate =
    Math.ceil(
        (
            requiredDeliveryDate.getTime() -
            today.getTime()
        ) /
        (1000 * 60 * 60 * 24)
    );


// Do not allow negative planning horizon
daysUntilRequiredDate =
    Math.max(
        0,
        daysUntilRequiredDate
    );


// ============================================================
// 8. CREATE SUPPLIER RISK LOOKUP
// ============================================================

const riskBySupplier = {};

for (const risk of riskRecords) {

    let riskLevel = null;


    // --------------------------------------------------------
    // First use explicitly supplied risk level
    // --------------------------------------------------------

    if (
        risk.status_details &&
        risk.status_details.risk_level
    ) {

        riskLevel =
            String(
                risk.status_details.risk_level
            ).toUpperCase();
    }


    // --------------------------------------------------------
    // Otherwise derive risk deterministically
    // --------------------------------------------------------

    if (!riskLevel) {

        if (
            risk.operational_status === "AT_RISK" ||
            risk.delivery_status === "DELAYED"
        ) {

            riskLevel = "HIGH";

        }
        else if (
            Number(
                risk.capacity_utilization || 0
            ) >= 0.85
        ) {

            riskLevel = "MEDIUM";

        }
        else {

            riskLevel = "LOW";
        }
    }


    riskBySupplier[
        risk.supplier_code
    ] = {

        operational_status:
            risk.operational_status ||
            "UNKNOWN",

        delivery_status:
            risk.delivery_status ||
            "UNKNOWN",

        capacity_utilization:
            Number(
                risk.capacity_utilization || 0
            ),

        quality_status:
            risk.quality_status ||
            "UNKNOWN",

        inventory_status:
            risk.inventory_status ||
            "UNKNOWN",

        risk_level:
            riskLevel,

        last_update_at:
            risk.last_update_at ||
            null,

        missed_update_count:
            Number(
                risk.missed_update_count || 0
            ),

        status_details:
            risk.status_details || {}
    };
}


// ============================================================
// 9. RISK SCORE FUNCTION
// ============================================================
//
// LOW     = 100
// MEDIUM  = 50
// HIGH    = 0
// UNKNOWN = 25
//
// Higher score = better
// ============================================================

function getRiskScore(riskLevel) {

    const level =
        String(
            riskLevel || "UNKNOWN"
        ).toUpperCase();


    if (level === "LOW") {
        return 100;
    }

    if (level === "MEDIUM") {
        return 50;
    }

    if (level === "HIGH") {
        return 0;
    }

    return 25;
}


// ============================================================
// 10. FIND LOWEST SUPPLIER PRICE
// ============================================================

const prices = [];

for (const supplier of commercialRecords) {

    const price =
        Number(
            supplier.reference_unit_price || 0
        );

    if (price > 0) {
        prices.push(price);
    }
}

const minimumPrice =
    prices.length > 0
        ? Math.min(...prices)
        : 0;


// ============================================================
// 11. FIND CURRENT AT-RISK / DELAYED SUPPLIER
// ============================================================

let currentSupplier = null;

for (const risk of riskRecords) {

    if (
        risk.operational_status === "AT_RISK" ||
        risk.delivery_status === "DELAYED"
    ) {

        currentSupplier =
            risk.supplier_code;

        break;
    }
}


// ============================================================
// 12. EVALUATE EACH SUPPLIER
// ============================================================

const evaluatedSuppliers = [];

for (const supplier of commercialRecords) {

    const supplierCode =
        supplier.supplier_code;


    // --------------------------------------------------------
    // Get matching risk record
    // --------------------------------------------------------

    let risk =
        riskBySupplier[supplierCode];


    // If no risk record exists
    if (!risk) {

        risk = {

            operational_status:
                "UNKNOWN",

            delivery_status:
                "UNKNOWN",

            capacity_utilization:
                null,

            quality_status:
                "UNKNOWN",

            inventory_status:
                "UNKNOWN",

            risk_level:
                "UNKNOWN",

            last_update_at:
                null,

            missed_update_count:
                0,

            status_details:
                {}
        };
    }


    // --------------------------------------------------------
    // Numerical values
    // --------------------------------------------------------

    const leadTime =
        Number(
            supplier.lead_time_days || 0
        );

    const minimumOrderQuantity =
        Number(
            supplier.minimum_order_quantity || 0
        );

    const unitPrice =
        Number(
            supplier.reference_unit_price || 0
        );


    // --------------------------------------------------------
    // CONSTRAINT 1
    // Supplier must be qualified
    // --------------------------------------------------------

    const qualified =
        supplier.is_qualified === true;


    // --------------------------------------------------------
    // CONSTRAINT 2
    // MOQ must be satisfiable
    // --------------------------------------------------------

    const moqFeasible =
        minimumOrderQuantity <=
        requiredQuantity;


    // --------------------------------------------------------
    // CONSTRAINT 3
    // Lead time must meet required date
    // --------------------------------------------------------

    const deliveryFeasible =
        leadTime <=
        daysUntilRequiredDate;


    // --------------------------------------------------------
    // OVERALL FEASIBILITY
    // --------------------------------------------------------

    const feasible =
        qualified &&
        moqFeasible &&
        deliveryFeasible;


    // ========================================================
    // 13. LEAD TIME SCORE
    // ========================================================

    let leadTimeScore = 0;

    if (
        leadTime <=
        daysUntilRequiredDate
    ) {

        leadTimeScore = 100;

    }
    else if (
        leadTime > 0
    ) {

        leadTimeScore =
            (
                daysUntilRequiredDate /
                leadTime
            ) * 100;

        leadTimeScore =
            Math.max(
                0,
                Math.min(
                    100,
                    leadTimeScore
                )
            );
    }


    // ========================================================
    // 14. PRICE SCORE
    // ========================================================

    let priceScore = 0;

    if (
        minimumPrice > 0 &&
        unitPrice > 0
    ) {

        priceScore =
            (
                minimumPrice /
                unitPrice
            ) * 100;

        priceScore =
            Math.max(
                0,
                Math.min(
                    100,
                    priceScore
                )
            );
    }


    // ========================================================
    // 15. RISK SCORE
    // ========================================================

    const riskScore =
        getRiskScore(
            risk.risk_level
        );


    // ========================================================
    // 16. PREFERRED SUPPLIER SCORE
    // ========================================================

    const preferredSupplier =
        supplier.is_preferred_supplier === true;

    const preferredScore =
        preferredSupplier
            ? 100
            : 0;


    // ========================================================
    // 17. OVERALL DETERMINISTIC SCORE
    // ========================================================
    //
    // Risk        = 40%
    // Lead Time   = 30%
    // Price       = 25%
    // Preferred   = 5%
    //
    // Total       = 100%
    // ========================================================

    const overallScore =
        (
            riskScore * 0.40
        ) +
        (
            leadTimeScore * 0.30
        ) +
        (
            priceScore * 0.25
        ) +
        (
            preferredScore * 0.05
        );


    // ========================================================
    // 18. RECOMMENDED QUANTITY
    // ========================================================

    const recommendedQuantity =
        Math.max(
            requiredQuantity,
            minimumOrderQuantity
        );


    // ========================================================
    // 19. CREATE EVALUATED SUPPLIER OBJECT
    // ========================================================

    evaluatedSuppliers.push({

        supplier_code:
            supplierCode,

        supplier_name:
            supplier.supplier_name,

        lead_time_days:
            leadTime,

        minimum_order_quantity:
            minimumOrderQuantity,

        reference_unit_price:
            unitPrice,

        currency:
            supplier.currency ||
            "INR",

        qualified:
            qualified,

        preferred_supplier:
            preferredSupplier,


        // ----------------------------------------------------
        // Risk
        // ----------------------------------------------------

        risk_level:
            risk.risk_level,

        operational_status:
            risk.operational_status,

        delivery_status:
            risk.delivery_status,

        capacity_utilization:
            risk.capacity_utilization,

        quality_status:
            risk.quality_status,

        inventory_status:
            risk.inventory_status,

        missed_update_count:
            risk.missed_update_count,

        status_details:
            risk.status_details,


        // ----------------------------------------------------
        // Requirement
        // ----------------------------------------------------

        required_quantity:
            requiredQuantity,

        recommended_quantity:
            recommendedQuantity,

        days_until_required_date:
            daysUntilRequiredDate,


        // ----------------------------------------------------
        // Constraints
        // ----------------------------------------------------

        constraints: {

            qualified:
                qualified,

            moq_feasible:
                moqFeasible,

            delivery_feasible:
                deliveryFeasible,

            feasible:
                feasible
        },


        // ----------------------------------------------------
        // Scores
        // ----------------------------------------------------

        scores: {

            risk_score:
                Number(
                    riskScore.toFixed(2)
                ),

            lead_time_score:
                Number(
                    leadTimeScore.toFixed(2)
                ),

            price_score:
                Number(
                    priceScore.toFixed(2)
                ),

            preferred_supplier_score:
                Number(
                    preferredScore.toFixed(2)
                ),

            overall_score:
                Number(
                    overallScore.toFixed(2)
                )
        }
    });
}


// ============================================================
// 20. RANK SUPPLIERS
// ============================================================
//
// Priority:
// 1. Feasible suppliers
// 2. Highest deterministic score
// ============================================================

evaluatedSuppliers.sort(
    function(a, b) {

        // Feasible suppliers first

        if (
            a.constraints.feasible !==
            b.constraints.feasible
        ) {

            return a.constraints.feasible
                ? -1
                : 1;
        }


        // Highest score first

        return (
            b.scores.overall_score -
            a.scores.overall_score
        );
    }
);


// ============================================================
// 21. GET FEASIBLE SUPPLIERS
// ============================================================

const feasibleSuppliers =
    evaluatedSuppliers.filter(
        function(supplier) {

            return supplier.constraints.feasible;
        }
    );


// ============================================================
// 22. SELECT TOP COMPUTED RECOMMENDATION
// ============================================================

const recommendedSupplier =
    feasibleSuppliers.length > 0
        ? feasibleSuppliers[0]
        : null;


// ============================================================
// 23. CREATE FINAL DECISION SUMMARY
// ============================================================

const decisionSummary = {

    status:
        "SUCCESS",

    decision_type:
        "SUPPLIER_MITIGATION_EVALUATION",


    // --------------------------------------------------------
    // Component
    // --------------------------------------------------------

    component_id:
        planning.component_id,

    component_code:
        planning.component_code,

    component_name:
        planning.component_name,


    // --------------------------------------------------------
    // Vehicle
    // --------------------------------------------------------

    vehicle_model_id:
        planning.vehicle_model_id,

    vehicle_model_code:
        planning.model_code,

    vehicle_model_name:
        planning.model_name,


    // --------------------------------------------------------
    // Customer order
    // --------------------------------------------------------

    customer_order_id:
        planning.customer_order_id,

    order_number:
        planning.order_number,

    customer_name:
        planning.customer_name,

    priority:
        planning.priority_level,

    order_status:
        planning.status,

    required_delivery_date:
        planning.required_delivery_date,


    // --------------------------------------------------------
    // Requirement
    // --------------------------------------------------------

    required_quantity:
        requiredQuantity,

    available_inventory:
        availableInventory,

    shortage_quantity:
        shortageQuantity,

    days_until_required_date:
        daysUntilRequiredDate,


    // --------------------------------------------------------
    // Supplier context
    // --------------------------------------------------------

    current_supplier:
        currentSupplier,

    evaluated_supplier_count:
        evaluatedSuppliers.length,

    feasible_supplier_count:
        feasibleSuppliers.length,


    // --------------------------------------------------------
    // Computed recommendation
    // --------------------------------------------------------

    recommended_supplier:
        recommendedSupplier
            ? recommendedSupplier.supplier_code
            : null,

    recommended_supplier_name:
        recommendedSupplier
            ? recommendedSupplier.supplier_name
            : null,

    recommended_quantity:
        recommendedSupplier
            ? recommendedSupplier.recommended_quantity
            : null,

    recommendation_score:
        recommendedSupplier
            ? recommendedSupplier.scores.overall_score
            : null,


    // --------------------------------------------------------
    // Governance
    // --------------------------------------------------------

    human_approval_required:
        true,

    autonomous_execution_allowed:
        false,


    // --------------------------------------------------------
    // Scoring methodology
    // --------------------------------------------------------

    scoring_methodology: {

        risk_weight:
            0.40,

        lead_time_weight:
            0.30,

        price_weight:
            0.25,

        preferred_supplier_weight:
            0.05
    },


    // --------------------------------------------------------
    // Supplier evaluation
    // --------------------------------------------------------

    supplier_options:
        evaluatedSuppliers
};


// ============================================================
// 24. RETURN TRANSFORMED DATA
// ============================================================

return [
    {
        json: decisionSummary
    }
];
